// All routing and snapping is performed by FastAPI against PostGIS.
let requestId=0;
async function api(path,body){const response=await fetch(path,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{});const data=await response.json();if(!response.ok)throw new Error(typeof data.detail==='string'?data.detail:'Unable to complete this request.');return data;}
const $=id=>document.getElementById(id);
const from=$('from'),to=$('to');
let graph,data,choices=[],routes={},selected='cool',pickMode=null,canopyVisible=false;
const selections={from:null,to:null};
const map=L.map('map',{zoomControl:false,minZoom:13,maxZoom:19}).setView([-33.891,151.192],16);
L.control.zoom({position:'topright'}).addTo(map);
const tiles=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'}).addTo(map);
let tileErrors=0;tiles.on('tileerror',()=>{if(++tileErrors>=3)$('tile-warning').hidden=false;});tiles.on('tileload',()=>{$('tile-warning').hidden=true;});
const base=L.layerGroup().addTo(map),cover=L.layerGroup(),paths=L.layerGroup().addTo(map),pins=L.layerGroup().addTo(map);
function clearRoute(){requestId++;routes={};$('results').hidden=true;paths.clearLayers();pins.clearLayers();}
function message(text){$('status').textContent=text;}
function distance(m){return m>=1000?`${(m/1000).toFixed(2)} km`:`${Math.round(m)} m`;}
function escape(text){return String(text).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function minutes(r){return Math.max(1,Math.ceil(r.distance/80));}
function selection(id){const el=$(id);if(selections[id]?.label===el.value)return selections[id];const c=choices.find(c=>c.name.toLowerCase()===el.value.trim().toLowerCase());if(!c)return null;return {...c,label:el.value};}
function setSelection(id,p,label){selections[id]={...p,label};$(id).value=label;}
function boundsPadding(){return matchMedia('(max-width:700px)').matches?{paddingTopLeft:[35,80],paddingBottomRight:[35,innerHeight*.55]}:{paddingTopLeft:[430,100],paddingBottomRight:[90,70]};}
function fit(){const r=routes[selected];if(r?.coordinates.length>1)map.fitBounds(r.coordinates,boundsPadding());else if(data)map.fitBounds(data.nodes.map(n=>[n.lat,n.lon]),boundsPadding());}
function draw(){paths.clearLayers();pins.clearLayers();const active=routes[selected];if(!active)return;const other=routes[selected==='cool'?'short':'cool'];if(other?.coordinates.length>1)L.polyline(other.coordinates,{color:'#8e9e9e',weight:5,opacity:.65}).addTo(paths);if(active.coordinates.length>1){L.polyline(active.coordinates,{color:'white',weight:10,opacity:.96}).addTo(paths);L.polyline(active.coordinates,{color:selected==='cool'?'#326d47':'#607e86',weight:6,opacity:1}).addTo(paths);}const endpoints=[active.nodes[0],active.nodes.at(-1)];endpoints.forEach((n,i)=>L.marker([n.lat,n.lon],{icon:L.divIcon({className:`map-pin ${i?'pin-b':''}`,html:i?'B':'A',iconSize:[31,31],iconAnchor:[15,15]})}).addTo(pins));}
function render(){const cool=routes.cool,short=routes.short;if(!cool||!short)return;$('results').hidden=false;let html='';for(const [key,r] of Object.entries(routes)){const name=key==='cool'?'Tree-aware walk':'Shortest walk';const pct=Math.round(r.canopyFraction*100);html+=`<button type="button" class="route-card ${key===selected?'selected':''}" data-route="${key}" aria-pressed="${key===selected}"><div class="card-title">${key==='cool'?'♧':'↗'} ${name}${key==='cool'?'<small>A* ROUTING</small>':''}</div><div class="card-stats"><strong>${minutes(r)} <span>min</span></strong><span>· ${distance(r.distance)}</span></div><div class="canopy-stat"><span class="bar"><i style="width:${pct}%"></i></span>${pct}% mapped canopy overlap</div></button>`;}$('route-cards').innerHTML=html;$('route-cards').querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>{selected=b.dataset.route;render();draw();}));
const delta=cool.distance-short.distance,pp=(cool.canopyFraction-short.canopyFraction)*100;$('comparison').textContent=Math.abs(delta)<1?'Both preferences choose the same route for this trip.':`Tree-aware: ${Math.round(delta)} m longer · ${pp>=0?'+':''}${Math.round(pp)} percentage points estimated canopy. Not measured shade.`;
const r=routes[selected],groups=[];for(const edge of r.edges){const name=edge.name||'Unnamed walking path';const last=groups.at(-1);if(last?.name===name)last.length+=edge.length;else groups.push({name,length:edge.length});}$('steps').innerHTML=groups.map((g,i)=>`<li>${i?'Continue along':'Start along'} ${escape(g.name)}<span>${distance(g.length)}</span></li>`).join('')+'<li>Arrive at the mapped destination point</li>';draw();}
async function calculate(fitMap=true){if(!graph)return;const a=selection('from'),b=selection('to');if(!a||!b){clearRoute();message('Choose a suggested place or use “Pick on map” for each point.');return;}clearRoute();const seq=requestId;message('Calculating your walk with FastAPI…');try{const result=await api('/api/routes',{start:{lat:a.lat,lon:a.lon},end:{lat:b.lat,lon:b.lon},preference:Number($('shade').value)});if(seq!==requestId)return;routes=result.routes;render();message('Routes begin and end on mapped paths. Check local access.');if(fitMap)fit();}catch(e){if(seq!==requestId)return;clearRoute();message(e.message||'The routing backend is unavailable. No browser fallback is used.');}}
$('route-form').addEventListener('submit',e=>{e.preventDefault();calculate();});
[from,to].forEach(el=>el.addEventListener('input',()=>{selections[el.id]=null;clearRoute();message('Choose a suggestion, then find your walk.');}));
$('swap').addEventListener('click',()=>{const v=from.value;from.value=to.value;to.value=v;const s=selections.from;selections.from=selections.to;selections.to=s;calculate();});
$('shade').addEventListener('input',()=>{$('preference-label').textContent=['Shortest','Gentle','Balanced','Leafier','Most canopy'][$('shade').value];if(graph&&selection('from')&&selection('to'))calculate(false);});
$('pick').addEventListener('click',()=>{pickMode=pickMode?null:'from';clearRoute();$('pick').textContent=pickMode?'× Cancel map pick':'⊙ Pick on map';message(pickMode?'Tap a mapped path to choose your starting point.':'Map selection cancelled.');});
map.on('click',async e=>{if(!pickMode||!graph)return;const mode=pickMode;clearRoute();const seq=requestId;try{const n=await api('/api/snap',{lat:e.latlng.lat,lon:e.latlng.lng});if(seq!==requestId||mode!==pickMode)return;setSelection(mode,n,`${mode==='from'?'Start':'Destination'} on map (${n.lat.toFixed(4)}, ${n.lon.toFixed(4)})`);L.circleMarker([n.lat,n.lon],{radius:7,color:'#174d40',fillOpacity:1}).addTo(pins);if(mode==='from'){pickMode='to';message('Now tap a mapped path for your destination.');}else{pickMode=null;$('pick').textContent='⌖ Pick on map';await calculate();}}catch(e){if(seq===requestId)message(e.message);}});
$('locate').addEventListener('click',()=>{if(!navigator.geolocation){message('Location is unavailable. Choose a place or pick on the map.');return;}clearRoute();const seq=requestId;message('Requesting your location.');$('locate').disabled=true;navigator.geolocation.getCurrentPosition(async p=>{try{if(seq!==requestId)return;await api('/api/snap',{lat:p.coords.latitude,lon:p.coords.longitude});if(seq!==requestId)return;setSelection('from',{lat:p.coords.latitude,lon:p.coords.longitude},'My location');await calculate();}catch(e){if(seq===requestId)message(e.message);}finally{$('locate').disabled=false;}},()=>{$('locate').disabled=false;if(seq===requestId)message('Could not access your location. Choose a place or pick on the map instead.');},{enableHighAccuracy:false,timeout:10000,maximumAge:30000});});
matchMedia('(max-width:700px)').addEventListener('change',()=>requestAnimationFrame(()=>{map.invalidateSize();fit();}));
$('fit').addEventListener('click',fit);$('canopy').addEventListener('click',()=>{canopyVisible=!canopyVisible;$('canopy').setAttribute('aria-pressed',String(canopyVisible));canopyVisible?cover.addTo(map):map.removeLayer(cover);});
$('about-open').addEventListener('click',()=>$('about').showModal());$('about-close').addEventListener('click',()=>$('about').close());$('about').addEventListener('click',e=>{if(e.target===$('about')){const r=$('about').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('about').close();}});
async function init(){try{data=await api('/api/network');graph=true;const nodeMap=new Map(data.nodes.map(n=>[n.id,n]));choices=[...(data.places||[])];const names=new Map();for(const e of data.edges){const node=nodeMap.get(e.u);if(e.name&&!names.has(e.name))names.set(e.name,{name:e.name,lat:node.lat,lon:node.lon});L.polyline(e.geometry||[[node.lat,node.lon],[nodeMap.get(e.v).lat,nodeMap.get(e.v).lon]],{color:'#a8b6a2',weight:2,opacity:.22,interactive:false}).addTo(base);if(e.shade>.05)L.polyline(e.geometry,{color:'#77a448',weight:Math.max(3,e.shade*16),opacity:.12+e.shade*.25,interactive:false}).addTo(cover);}choices.push(...names.values());choices=choices.filter((c,i,a)=>a.findIndex(x=>x.name===c.name)===i);$('places').innerHTML=choices.map(c=>`<option value="${escape(c.name)}"></option>`).join('');(data.places||[]).forEach(p=>L.circleMarker([p.lat,p.lon],{radius:3,color:'#73856a',weight:1,fillOpacity:1}).bindTooltip(p.name,{permanent:true,direction:'right',className:'place-label'}).addTo(base));
const start=choices.find(p=>/redfern/i.test(p.name))||choices[0],end=choices.find(p=>/university|engineering|sydney uni/i.test(p.name))||choices[1];if(start&&end){setSelection('from',start,start.name);setSelection('to',end,end.name);await calculate();}else{message('Choose your points on the map to find a walk.');fit();}
$('data-summary').textContent=`The backend uses ${data.nodes.length.toLocaleString()} nodes and ${data.edges.length.toLocaleString()} path segments from PostGIS. GeoPandas and Shapely calculate exact overlap of buffered tree crowns and road corridors using the original tree inventory. NetworkX A* calculates both routes in FastAPI.`;
$('sources').innerHTML='<a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap contributors · ODbL ↗</a><br><a href="https://data.cityofsydney.nsw.gov.au/" target="_blank" rel="noopener">City of Sydney tree inventory ↗</a><p>City of Sydney tree data: CC BY 4.0. Canopy corridor estimates are a CoolPath transformation. Routing is calculated by the local FastAPI backend.</p>';
}catch(e){message(e.message||'The FastAPI/PostGIS backend is unavailable. No browser routing fallback is used.');$('find-route').disabled=true;$('pick').disabled=true;$('locate').disabled=true;console.error(e);}}
init();
